fn prime_num(n: u64) -> bool {
    // Handle the smallest prime
    if n == 2 {
        return true;
    }
    
    // Even numbers greater than 2 are not prime
    if n % 2 == 0 {
        return false;
    }
    
    // Check odd divisors from 3 up to sqrt(n)
    let mut divisor = 3;
    while divisor * divisor <= n {
        if n % divisor == 0 {
            return false;
        }
        divisor += 2;
    }
    
    // If no divisors found, n is prime
    true
}